/* circular arc as a path: centre, radius, angles in degrees (screen: 0 = right, 90 = down) */
const MD_arcP=(cx,cy,r,a0,a1)=>{const p=a=>[cx+r*Math.cos(a*Math.PI/180),cy+r*Math.sin(a*Math.PI/180)];const [x0,y0]=p(a0),[x1,y1]=p(a1);return `M${x0.toFixed(1)},${y0.toFixed(1)} A${r},${r} 0 ${Math.abs(a1-a0)>180?1:0} ${a1>a0?1:0} ${x1.toFixed(1)},${y1.toFixed(1)}`};
/* annular sector (curved beam body) */
const MD_sector=(cx,cy,ri,ro,a0,a1,fill,st)=>{const p=(r,a)=>[cx+r*Math.cos(a*Math.PI/180),cy+r*Math.sin(a*Math.PI/180)].map(v=>v.toFixed(1)).join(',');const lg=Math.abs(a1-a0)>180?1:0;
 return `<path d="M${p(ro,a0)} A${ro},${ro} 0 ${lg} 1 ${p(ro,a1)} L${p(ri,a1)} A${ri},${ri} 0 ${lg} 0 ${p(ri,a0)} Z" fill="${fill}" stroke="${st}" stroke-width="3"/>`};
