  MD_T(484,y[0]+48,'allowable',{fs:22,fw:800,fill:RED})+MD_T(484,y[0]+100,'stress',{fs:22,fw:800,fill:BLU})+MD_T(484,y[0]+128,'below it',{fs:22,fill:MD_GREY});
 const r2=MD_box(14,y[1],612,156,{st:ORG,sw:3})+beam(50,y[1]+50,0,MD_LIGHT)+beam(50,y[1]+50,46,ORG)+MD_L(200,y[1]+50,200,y[1]+96,MD_DARK,2)+MD_dbl(222,y[1]+56,222,y[1]+96,ORG,3)+MD_T(232,y[1]+84,'δ',{fs:26,fw:800,fill:ORG})+
  MD_L(60,y[1]+112,340,y[1]+112,RED,3,'stroke-dasharray="8 6"')+MD_T(60,y[1]+140,'limit set by the machine',{fs:22,fill:MD_GREY})+MD_T(400,y[1]+60,'deflection',{fs:24,fw:800,fill:ORG})+MD_T(400,y[1]+92,'and twist under',{fs:22,fill:MD_GREY})+MD_T(400,y[1]+122,'their limits',{fs:22,fill:MD_GREY});
