  MD_T(100,y[2]+152,'b',{fs:22,fw:800,a:'middle',fill:PUR})+MD_T(154,y[2]+84,'h',{fs:22,fw:800,fill:PUR})+
  MD_T(210,y[2]+56,'strength: Z = bh²/6',{fs:24,fw:800,fill:BLU})+MD_T(210,y[2]+96,'stiffness: I = bh³/12, with E',{fs:24,fw:800,fill:ORG})+MD_T(210,y[2]+132,'torsion: J/r and J, with G',{fs:22,fill:MD_GREY});
