 bx.forEach(([x,t],i)=>{r4+=MD_box(x,y[3]+28,120,52,{fill:'#EBFBEE',st:GRN,sw:3,r:10})+MD_T(x+60,y[3]+62,t,{fs:22,fw:800,a:'middle',fill:GRN});if(i<3)r4+=MD_arrow(x+122,y[3]+54,x+148,y[3]+54,GRN,3,10)});
